#[unsafe(no_mangle)]
pub unsafe extern "C" fn connect_norito_encode_transfer_instruction_box(
    authority_ptr: *const c_char,
    authority_len: c_ulong,
    asset_definition_ptr: *const c_char,
    asset_definition_len: c_ulong,
    quantity_ptr: *const c_char,
    quantity_len: c_ulong,
    destination_ptr: *const c_char,
    destination_len: c_ulong,
    out_instruction_ptr: *mut *mut c_uchar,
    out_instruction_len: *mut c_ulong,
) -> c_int {
    let result = (|| {
        if out_instruction_ptr.is_null() || out_instruction_len.is_null() {
            return Err(BridgeError::NullPtr);
        }

        let authority =
            parse_account_id(unsafe { read_string_bridge(authority_ptr, authority_len) }?)?;
        let asset_definition =
            unsafe { read_string_bridge(asset_definition_ptr, asset_definition_len) }?;
        let quantity = parse_quantity(unsafe { read_string_bridge(quantity_ptr, quantity_len) }?)?;
        let destination =
            parse_destination(unsafe { read_string_bridge(destination_ptr, destination_len) }?)?;
        let (asset_definition, asset_scope) =
            parse_asset_definition_with_balance_scope(asset_definition)?;
        let asset_id = AssetId::with_scope(asset_definition, authority, asset_scope);
        let instruction =
            InstructionBox::from(Transfer::asset_quantity(asset_id, quantity, destination));
        let instruction_bytes =
            norito::core::to_bytes(&instruction).map_err(|_| BridgeError::JsonSerialize)?;

        unsafe {
            write_bytes_bridge(out_instruction_ptr, out_instruction_len, &instruction_bytes)
        }?;
        Ok(())
    })();

    bridge_result_to_code(result)
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn connect_norito_encode_validation_fee_transfer_signed_transaction(
    chain_ptr: *const c_char,
    chain_len: c_ulong,
    authority_ptr: *const c_char,
    authority_len: c_ulong,
    creation_time_ms: u64,
    ttl_ms: u64,
    ttl_present: c_uchar,
    nonce: u32,
    nonce_present: c_uchar,
    principal_asset_definition_ptr: *const c_char,
    principal_asset_definition_len: c_ulong,
    principal_quantity_ptr: *const c_char,
    principal_quantity_len: c_ulong,
    destination_ptr: *const c_char,
    destination_len: c_ulong,
    fee_asset_definition_ptr: *const c_char,
    fee_asset_definition_len: c_ulong,
    fee_quantity_ptr: *const c_char,
    fee_quantity_len: c_ulong,
    treasury_ptr: *const c_char,
    treasury_len: c_ulong,
    policy_version: u64,
    policy_hash_ptr: *const c_char,
    policy_hash_len: c_ulong,
    fee_instruction_index: u64,
    fee_sponsor_ptr: *const c_char,
    fee_sponsor_len: c_ulong,
    memo_ptr: *const c_char,
    memo_len: c_ulong,
    metadata_json_ptr: *const c_char,
    metadata_json_len: c_ulong,
    private_key_ptr: *const c_uchar,
    private_key_len: c_ulong,
    out_signed_ptr: *mut *mut c_uchar,
    out_signed_len: *mut c_ulong,
    out_hash_ptr: *mut c_uchar,
    out_hash_len: c_ulong,
) -> c_int {
    let result = (|| {
        if out_signed_ptr.is_null() || out_signed_len.is_null() || out_hash_ptr.is_null() {
            return Err(BridgeError::NullPtr);
        }

        let inputs = unsafe {
            gather_asset_tx_inputs(AssetInputPointers {
                chain_ptr,
                chain_len,
                authority_ptr,
                authority_len,
                asset_definition_ptr: principal_asset_definition_ptr,
                asset_definition_len: principal_asset_definition_len,
                quantity_ptr: principal_quantity_ptr,
                quantity_len: principal_quantity_len,
                destination_ptr,
                destination_len,
                ttl_ms,
                ttl_present,
                private_key_ptr,
                private_key_len,
            })?
        };

        let fee_asset_definition =
            unsafe { read_string_bridge(fee_asset_definition_ptr, fee_asset_definition_len) }?;
        let fee_quantity = unsafe { read_string_bridge(fee_quantity_ptr, fee_quantity_len) }?;
        let treasury = unsafe { read_string_bridge(treasury_ptr, treasury_len) }?;
        let policy_hash = unsafe { read_string_bridge(policy_hash_ptr, policy_hash_len) }?;
        let fee_sponsor =
            unsafe { parse_optional_account_id_bridge(fee_sponsor_ptr, fee_sponsor_len)? };
        let memo = unsafe { parse_optional_string_bridge(memo_ptr, memo_len)? };
        let metadata =
            unsafe { parse_metadata_object_bridge(metadata_json_ptr, metadata_json_len)? };
        let metadata = build_validation_fee_metadata(
            metadata,
            policy_version,
            policy_hash,
            fee_instruction_index,
            fee_sponsor,
            memo,
        )?;

        let (fee_asset_definition, fee_asset_scope) =
            parse_asset_definition_with_balance_scope(fee_asset_definition)?;
        let fee_quantity = parse_quantity(fee_quantity)?;
        let treasury = parse_destination(treasury)?;

        let AssetTxInputs {
            chain_id,
            authority,
            asset_definition,
            asset_scope,
            destination,
            quantity,
            ttl,
            private_key,
        } = inputs;
        let nonce = parse_nonce(nonce, nonce_present != 0)?;

        let principal_asset_id =
            AssetId::with_scope(asset_definition.clone(), authority.clone(), asset_scope);
        let fee_asset_id = AssetId::with_scope(
            fee_asset_definition.clone(),
            authority.clone(),
            fee_asset_scope,
        );
        let (signed_bytes, hash_bytes) = encode_asset_transaction_with_nonce_and_metadata(
            chain_id,
            authority,
            creation_time_ms,
            ttl,
            nonce,
            metadata,
            private_key,
            || {
                let principal_transfer =
                    Transfer::asset_quantity(principal_asset_id, quantity, destination);
                let fee_transfer = Transfer::asset_quantity(fee_asset_id, fee_quantity, treasury);
                Executable::from([
                    InstructionBox::from(principal_transfer),
                    InstructionBox::from(fee_transfer),
                ])
            },
        )?;

        write_hash(out_hash_ptr, out_hash_len, &hash_bytes)?;
        unsafe { write_bytes_bridge(out_signed_ptr, out_signed_len, &signed_bytes) }?;
        Ok(())
    })();

    bridge_result_to_code(result)
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn connect_norito_encode_shield_signed_transaction(
    chain_ptr: *const c_char,
    chain_len: c_ulong,
    authority_ptr: *const c_char,
    authority_len: c_ulong,
    creation_time_ms: u64,
    ttl_ms: u64,
    ttl_present: c_uchar,
    asset_definition_ptr: *const c_char,
    asset_definition_len: c_ulong,
    from_ptr: *const c_char,
    from_len: c_ulong,
    amount_ptr: *const c_char,
    amount_len: c_ulong,
    note_commitment_ptr: *const c_uchar,
    note_commitment_len: c_ulong,
    payload_ephemeral_ptr: *const c_uchar,
    payload_ephemeral_len: c_ulong,
    payload_nonce_ptr: *const c_uchar,
    payload_nonce_len: c_ulong,
    payload_ciphertext_ptr: *const c_uchar,
    payload_ciphertext_len: c_ulong,
    private_key_ptr: *const c_uchar,
    private_key_len: c_ulong,
    out_signed_ptr: *mut *mut c_uchar,
    out_signed_len: *mut c_ulong,
    out_hash_ptr: *mut c_uchar,
    out_hash_len: c_ulong,
) -> c_int {
    let result = (|| {
        if out_signed_ptr.is_null() || out_signed_len.is_null() || out_hash_ptr.is_null() {
            return Err(BridgeError::NullPtr);
        }
        let inputs = unsafe {
            gather_shield_tx_inputs(ShieldInputPointers {
                chain_ptr,
                chain_len,
                authority_ptr,
                authority_len,
                asset_definition_ptr,
                asset_definition_len,
                from_ptr,
                from_len,
                amount_ptr,
                amount_len,
                ttl_ms,
                ttl_present,
                private_key_ptr,
                private_key_len,
            })?
        };

        if payload_ciphertext_len > u32::MAX as c_ulong {
            return Err(BridgeError::ConfidentialPayload);
        }

        let note_commitment = unsafe {
            read_fixed_array::<32>(
                note_commitment_ptr,
                note_commitment_len,
                BridgeError::InvalidNoteCommitment,
            )?
        };
        let ephemeral = unsafe {
            read_fixed_array::<32>(
                payload_ephemeral_ptr,
                payload_ephemeral_len,
                BridgeError::ConfidentialPayload,
            )?
        };
        let nonce = unsafe {
            read_fixed_array::<24>(
                payload_nonce_ptr,
                payload_nonce_len,
                BridgeError::ConfidentialPayload,
            )?
        };
        let ciphertext = unsafe { read_vec_bytes(payload_ciphertext_ptr, payload_ciphertext_len)? };

        let payload = build_confidential_encrypted_payload(ephemeral, nonce, ciphertext)?;
        let asset = inputs.asset_definition.clone();
        let from_account = inputs.from_account.clone();
        let ttl = inputs.ttl;
        let amount = inputs.amount;
        let chain_id = inputs.chain_id;
        let authority = inputs.authority;
        let private_key = inputs.private_key;

        let (signed_bytes, hash_bytes) = encode_asset_transaction(
            chain_id,
            authority,
            creation_time_ms,
            ttl,
            private_key,
            || {
                let instruction = zk::Shield::new(
                    asset.clone(),
                    from_account.clone(),
                    amount,
                    note_commitment,
                    payload.clone(),
                );
                Executable::from([InstructionBox::from(instruction)])
            },
        )?;

        write_hash(out_hash_ptr, out_hash_len, &hash_bytes)?;
        unsafe { write_bytes_bridge(out_signed_ptr, out_signed_len, &signed_bytes) }?;
        Ok(())
    })();

    bridge_result_to_code(result)
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn connect_norito_encode_shield_signed_transaction_alg(
    chain_ptr: *const c_char,
    chain_len: c_ulong,
    authority_ptr: *const c_char,
    authority_len: c_ulong,
    creation_time_ms: u64,
    ttl_ms: u64,
    ttl_present: c_uchar,
    asset_definition_ptr: *const c_char,
    asset_definition_len: c_ulong,
    from_ptr: *const c_char,
    from_len: c_ulong,
    amount_ptr: *const c_char,
    amount_len: c_ulong,
    note_commitment_ptr: *const c_uchar,
    note_commitment_len: c_ulong,
    payload_ephemeral_ptr: *const c_uchar,
    payload_ephemeral_len: c_ulong,
    payload_nonce_ptr: *const c_uchar,
    payload_nonce_len: c_ulong,
    payload_ciphertext_ptr: *const c_uchar,
    payload_ciphertext_len: c_ulong,
    private_key_ptr: *const c_uchar,
    private_key_len: c_ulong,
    algorithm_code: u8,
    out_signed_ptr: *mut *mut c_uchar,
    out_signed_len: *mut c_ulong,
    out_hash_ptr: *mut c_uchar,
    out_hash_len: c_ulong,
) -> c_int {
    let result = (|| {
        if out_signed_ptr.is_null() || out_signed_len.is_null() || out_hash_ptr.is_null() {
            return Err(BridgeError::NullPtr);
        }
        let algorithm = parse_algorithm_code(algorithm_code)?;
        let inputs = unsafe {
            gather_shield_tx_inputs_with_parser(
                ShieldInputPointers {
                    chain_ptr,
                    chain_len,
                    authority_ptr,
                    authority_len,
                    asset_definition_ptr,
                    asset_definition_len,
                    from_ptr,
                    from_len,
                    amount_ptr,
                    amount_len,
                    ttl_ms,
                    ttl_present,
                    private_key_ptr,
                    private_key_len,
                },
                |bytes| parse_private_key_with_algorithm(bytes, algorithm),
            )?
        };

        if payload_ciphertext_len > u32::MAX as c_ulong {
            return Err(BridgeError::ConfidentialPayload);
        }

        let note_commitment = unsafe {
            read_fixed_array::<32>(
                note_commitment_ptr,
                note_commitment_len,
                BridgeError::InvalidNoteCommitment,
            )?
        };
        let ephemeral = unsafe {
            read_fixed_array::<32>(
                payload_ephemeral_ptr,
                payload_ephemeral_len,
                BridgeError::ConfidentialPayload,
            )?
        };
        let nonce = unsafe {
            read_fixed_array::<24>(
                payload_nonce_ptr,
                payload_nonce_len,
                BridgeError::ConfidentialPayload,
            )?
        };
        let ciphertext = unsafe { read_vec_bytes(payload_ciphertext_ptr, payload_ciphertext_len)? };
        let payload = build_confidential_encrypted_payload(ephemeral, nonce, ciphertext)?;

        let ShieldTxInputs {
            chain_id,
            authority,
            asset_definition,
            from_account,
            amount,
            ttl,
            private_key,
        } = inputs;

        let (signed_bytes, hash_bytes) = encode_asset_transaction(
            chain_id,
            authority,
            creation_time_ms,
            ttl,
            private_key,
            || {
                let instruction = zk::Shield::new(
                    asset_definition,
                    from_account,
                    amount,
                    note_commitment,
                    payload,
                );
                Executable::from([InstructionBox::from(instruction)])
            },
        )?;

        write_hash(out_hash_ptr, out_hash_len, &hash_bytes)?;
        unsafe { write_bytes_bridge(out_signed_ptr, out_signed_len, &signed_bytes) }?;
        Ok(())
    })();

    bridge_result_to_code(result)
}

