    #[test]
    fn privacy_production_evidence_rejects_missing_and_duplicate_rows() {
        let entry =
            privacy_algorithm_entry("zk-ace-pq-authorization-v0").expect("ZK-ACE catalog row");
        let row = privacy_test_evidence_row(entry);

        let no_chain_capabilities = privacy_capabilities_with_production_evidence(&[row], None);
        let zk_ace = no_chain_capabilities
            .algorithms
            .iter()
            .find(|algorithm| algorithm.algorithm_id == entry.id)
            .expect("ZK-ACE capability row");
        assert!(
            !zk_ace.production_ready,
            "evidence cannot admit production readiness without expected chain binding",
        );

        let duplicate_capabilities = privacy_capabilities_with_production_evidence(
            &[
                privacy_test_evidence_row(entry),
                privacy_test_evidence_row(entry),
            ],
            Some(PRIVACY_TEST_PRODUCTION_CHAIN_ID),
        );
        let duplicate_zk_ace = duplicate_capabilities
            .algorithms
            .iter()
            .find(|algorithm| algorithm.algorithm_id == entry.id)
            .expect("ZK-ACE capability row");
        assert!(
            !duplicate_zk_ace.production_ready,
            "duplicate valid evidence rows must not admit readiness",
        );
    }

    #[test]
    fn privacy_production_evidence_rejects_missing_chain_and_duplicates_for_all_rows() {
        for entry in PRIVACY_ALGORITHM_ENTRIES {
            let row = privacy_test_evidence_row(entry);

            let no_chain_capabilities =
                privacy_capabilities_with_production_evidence(std::slice::from_ref(&row), None);
            let no_chain_algorithm = no_chain_capabilities
                .algorithms
                .iter()
                .find(|algorithm| algorithm.algorithm_id == entry.id)
                .expect("privacy capability row");
            assert!(
                !no_chain_algorithm.production_ready,
                "evidence cannot admit {} without expected chain binding",
                entry.id,
            );

            let duplicate_capabilities = privacy_capabilities_with_production_evidence(
                &[row.clone(), row],
                Some(PRIVACY_TEST_PRODUCTION_CHAIN_ID),
            );
            let duplicate_algorithm = duplicate_capabilities
                .algorithms
                .iter()
                .find(|algorithm| algorithm.algorithm_id == entry.id)
                .expect("privacy capability row");
            assert!(
                !duplicate_algorithm.production_ready,
                "duplicate valid evidence rows must not admit {}",
                entry.id,
            );
        }
    }

    #[test]
    fn privacy_ffi_archives_use_public_schema_hashes() {
        let mut out_ptr: *mut c_uchar = ptr::null_mut();
        let mut out_len: c_ulong = 0;

        let capabilities_rc = unsafe { iroha_privacy_capabilities_v1(&mut out_ptr, &mut out_len) };
        assert_eq!(capabilities_rc, 0);
        let mut capabilities_archive = take_privacy_output_bytes(out_ptr, out_len);
        assert!(
            privacy_archive_has_repeated_schema_byte(
                &capabilities_archive,
                PRIVACY_CAPABILITIES_RESULT_SCHEMA_BYTE,
            ),
            "capabilities output must use the public privacy capabilities schema"
        );
        normalize_privacy_public_archive_for_decode::<PrivacyCapabilitiesV1>(
            &mut capabilities_archive,
        );
        let capabilities: PrivacyCapabilitiesV1 =
            norito::decode_from_bytes(&capabilities_archive).expect("decode capabilities");
        assert!(privacy_capabilities_invariants_hold(&capabilities));

        let build_request = privacy_request(
            "confidential-transfer-v2",
            "buildConfidentialTransferProofV2",
            Vec::new(),
        );
        let build_archive = public_privacy_request_archive(&build_request);
        assert!(
            privacy_archive_has_repeated_schema_byte(&build_archive, PRIVACY_REQUEST_SCHEMA_BYTE),
            "build request must use the public privacy request schema"
        );
        let build_rc = unsafe {
            iroha_privacy_build_proof_v1(
                build_archive.as_ptr(),
                build_archive.len() as c_ulong,
                &mut out_ptr,
                &mut out_len,
            )
        };
        assert_eq!(build_rc, 0);
        let mut build_result_archive = take_privacy_output_bytes(out_ptr, out_len);
        assert!(
            privacy_archive_has_repeated_schema_byte(
                &build_result_archive,
                PRIVACY_BUILD_PROOF_RESULT_SCHEMA_BYTE,
            ),
            "build output must use the public privacy build-result schema"
        );
        normalize_privacy_public_archive_for_decode::<PrivacyProofResultV1>(
            &mut build_result_archive,
        );
        let build_result: PrivacyProofResultV1 =
            norito::decode_from_bytes(&build_result_archive).expect("decode build result");
        assert_eq!(
            build_result.error_code,
            PRIVACY_IN_SCOPE_PLACEHOLDER_BUILD_ERROR_CODE
        );

        let mut verify_request = privacy_request(
            "confidential-transfer-v2",
            "buildConfidentialTransferProofV2",
            b"candidate-proof".to_vec(),
        );
        verify_request.witness.clear();
        let verify_archive = public_privacy_request_archive(&verify_request);
        assert!(
            privacy_archive_has_repeated_schema_byte(&verify_archive, PRIVACY_REQUEST_SCHEMA_BYTE),
            "verify request must use the public privacy request schema"
        );
        let verify_rc = unsafe {
            iroha_privacy_verify_proof_v1(
                verify_archive.as_ptr(),
                verify_archive.len() as c_ulong,
                &mut out_ptr,
                &mut out_len,
            )
        };
        assert_eq!(verify_rc, 0);
        let mut verify_result_archive = take_privacy_output_bytes(out_ptr, out_len);
        assert!(
            privacy_archive_has_repeated_schema_byte(
                &verify_result_archive,
                PRIVACY_VERIFY_PROOF_RESULT_SCHEMA_BYTE,
            ),
            "verify output must use the public privacy verify-result schema"
        );
        normalize_privacy_public_archive_for_decode::<PrivacyProofResultV1>(
            &mut verify_result_archive,
        );
        let verify_result: PrivacyProofResultV1 =
            norito::decode_from_bytes(&verify_result_archive).expect("decode verify result");
        assert_eq!(
            verify_result.error_code,
            PRIVACY_IN_SCOPE_PLACEHOLDER_VERIFY_ERROR_CODE
        );
    }

    #[cfg(feature = "privacy-production-enabled")]
    #[test]
    fn privacy_ffi_build_then_verify_emits_ok_proof_archive() {
        use crate::privacy_production::test_fixtures::{
            valid_transfer_witness_bytes, valid_unshield_witness_bytes,
        };

        let cases = [
            (
                "confidential-transfer-v2",
                "buildConfidentialTransferProofV2",
                valid_transfer_witness_bytes(),
            ),
            (
                "unshield",
                "buildConfidentialUnshieldProofV3",
                valid_unshield_witness_bytes(),
            ),
        ];

        for (algorithm_id, entrypoint, witness) in cases {
            let mut out_ptr: *mut c_uchar = ptr::null_mut();
            let mut out_len: c_ulong = 0;

            let mut build_request = privacy_request(algorithm_id, entrypoint, Vec::new());
            build_request.witness = witness;
            let build_archive = public_privacy_request_archive(&build_request);
            let build_rc = unsafe {
                iroha_privacy_build_proof_v1(
                    build_archive.as_ptr(),
                    build_archive.len() as c_ulong,
                    &mut out_ptr,
                    &mut out_len,
                )
            };
            assert_eq!(build_rc, 0, "{algorithm_id} build FFI return code");
            let mut build_result_archive = take_privacy_output_bytes(out_ptr, out_len);
            assert!(
                privacy_archive_has_repeated_schema_byte(
                    &build_result_archive,
                    PRIVACY_BUILD_PROOF_RESULT_SCHEMA_BYTE,
                ),
                "{algorithm_id} build output must use the public build-result schema"
            );
            normalize_privacy_public_archive_for_decode::<PrivacyProofResultV1>(
                &mut build_result_archive,
            );
            let build_result: PrivacyProofResultV1 =
                norito::decode_from_bytes(&build_result_archive).expect("decode build result");
            assert_eq!(
                build_result.status, PRIVACY_FFI_STATUS_OK,
                "{algorithm_id} build status must be OK"
            );
            assert_eq!(
                build_result.error_code, 0,
                "{algorithm_id} build error_code"
            );
            assert!(
                !build_result.proof.is_empty(),
                "{algorithm_id} build must emit a real proof envelope"
            );
            assert!(
                !build_result.verified,
                "{algorithm_id} build does not claim verified"
            );
            assert!(
                build_result.message.is_empty(),
                "{algorithm_id} build message"
            );

            let mut verify_request = privacy_request(algorithm_id, entrypoint, build_result.proof);
            verify_request.witness.clear();
            let verify_archive = public_privacy_request_archive(&verify_request);
            let verify_rc = unsafe {
                iroha_privacy_verify_proof_v1(
                    verify_archive.as_ptr(),
                    verify_archive.len() as c_ulong,
                    &mut out_ptr,
                    &mut out_len,
                )
            };
            assert_eq!(verify_rc, 0, "{algorithm_id} verify FFI return code");
            let mut verify_result_archive = take_privacy_output_bytes(out_ptr, out_len);
            normalize_privacy_public_archive_for_decode::<PrivacyProofResultV1>(
                &mut verify_result_archive,
            );
            let verify_result: PrivacyProofResultV1 =
                norito::decode_from_bytes(&verify_result_archive).expect("decode verify result");
            assert_eq!(
                verify_result.status, PRIVACY_FFI_STATUS_OK,
                "{algorithm_id} verify status must be OK"
            );
            assert_eq!(
                verify_result.error_code, 0,
                "{algorithm_id} verify error_code"
            );
            assert!(
                verify_result.verified,
                "{algorithm_id} verify must confirm the proof"
            );
        }
    }

